\"\"\"A tiny, dependency-free maze generator and solver.

The maze is an ASCII grid rendered on a character lattice. Each cell is
represented by four walls (N, E, S, W). We generate a perfect maze with
recursive backtracking, then solve it with a depth-first search.
\"\"\"

from __future__ import annotations

import random
from dataclasses import dataclass
from typing import Iterator

WALL = \"#\"
PATH = \" \"
START = \"S\"
END = \"E\"
VISITED = \".\"

# Direction helpers as (row, col) deltas keyed by wall names.
_DIRS = {
    \"N\": (-1, 0),
    \"S\": (1, 0),
    \"E\": (0, 1),
    \"W\": (0, -1),
}
_OPPOSITE = {\"N\": \"S\", \"S\": \"N\", \"E\": \"W\", \"W\": \"E\"}


@dataclass
class Cell:
    \"\"\"A single maze cell holding its four walls.\"\"\"

    row: int
    col: int
    walls: set[str]

    @property
    def neighbors(self) -> Iterator[str]:
        return iter(self.walls)


class Maze:
    def __init__(self, rows: int, cols: int, seed: int | None = None) -> None:
        if rows < 2 or cols < 2:
            raise ValueError(\"Maze must be at least 2x2 cells.\")
        self.rows = rows
        self.cols = cols
        self._rng = random.Random(seed)
        self.start = (0, 0)
        self.end = (rows - 1, cols - 1)
        self.grid = {
            (r, c): Cell(r, c, set(_DIRS))
            for r in range(rows)
            for c in range(cols)
        }
        self._carve()

    # -- generation -----------------------------------------------------
    def _carve(self) -> None:
        \"\"\"Recursive-backtracking pass that removes walls to make a maze.\"\"\"
        visited: set[tuple[int, int]] = set()
        stack: list[tuple[int, int]] = [self.start]

        while stack:
            row, col = stack[-1]
            if (row, col) not in visited:
                visited.add((row, col))

            neighbors = [
                (d, r, c)
                for d, (dr, dc) in _DIRS.items()
                if (
                    0 <= (r := row + dr) < self.rows
                    and 0 <= (c := col + dc) < self.cols
                    and (r, c) not in visited
                )
            ]

            if not neighbors:
                stack.pop()
                continue

            direction, nrow, ncol = self._rng.choice(neighbors)
            self.grid[(row, col)].walls.discard(direction)
            self.grid[(nrow, ncol)].walls.discard(_OPPOSITE[direction])
            stack.append((nrow, ncol))

    # -- rendering ------------------------------------------------------
    def render(self) -> str:
        \"\"\"Render the maze to a printable string.\"\"\"
        lines: list[str] = []
        height = self.rows * 2 + 1
        width = self.cols * 2 + 1
        for r in range(height):
            line = []
            for c in range(width):
                line.append(self._char_at(r, c))
            lines.append(\"\".join(line))
        return \"\\n\".join(lines)

    def line(self, index: int) -> str:
        \"\"\"Render a single row of the maze as a string.\"\"\"
        return \"\".join(self._char_at(index, c) for c in range(self.cols * 2 + 1))

    def _char_at(self, r: int, c: int) -> str:
        if r % 2 == 0:  # horizontal wall row
            return WALL if self._horizontal_wall(r, c) else PATH
        if c % 2 == 0:  # vertical wall column
            return WALL if self._vertical_wall(r, c) else PATH
        # interior cell
        cell = self.grid[(r // 2, c // 2)]
        if (r // 2, c // 2) == self.start:
            return START
        if (r // 2, c // 2) == self.end:
            return END
        return PATH

    def _horizontal_wall(self, r: int, c: int) -> bool:
        if r == 0:
            return True
        if r == self.rows * 2:
            return True
        # odd c = above a cell; open only if that cell is missing its N wall
        if c % 2 == 1:
            cell = self.grid[(r // 2 - 1, c // 2)]
            return \"N\" in cell.walls
        # even c = corner between four cells; open if either diagonal pair
        # of adjacent cells is open across the horizontal line
        top = self.grid[(r // 2 - 1, c // 2 - 1)]
        bot = self.grid[(r // 2, c // 2 - 1)]
        return not (\"S\" in top.walls or \"N\" in bot.walls)

    def _vertical_wall(self, r: int, c: int) -> bool:
        if c == 0:
            return True
        if c == self.cols * 2:
            return True
        # odd r = left of a cell; open only if that cell is missing its W wall
        if r % 2 == 1:
            cell = self.grid[(r // 2, c // 2 - 1)]
            return \"W\" in cell.walls
        # even r = corner; open if either diagonal pair is open vertically
        left = self.grid[(r // 2 - 1, c // 2 - 1)]
        right = self.grid[(r // 2 - 1, c // 2)]
        return not (\"S\" in left.walls or \"S\" in right.walls)

    # -- solving --------------------------------------------------------
    def solve(self) -> list[tuple[int, int]]:
        \"\"\"Return the path of (row, col) cells from start to end.

        Uses iterative DFS with an explicit stack. Raises if no path exists
        (which cannot happen for a perfect maze, since every cell is reachable).
        \"\"\"
        start = self.start
        end = self.end
        parent: dict[tuple[int, int], tuple[int, int] | None] = {start: None}
        stack = [start]

        while stack:
            cell = stack.pop()
            if cell == end:
                path = []
                cur: tuple[int, int] | None = end
                while cur is not None:
                    path.append(cur)
                    cur = parent[cur]
                path.reverse()
                return path

            row, col = cell
            for direction in self.grid[cell].walls:
                dr, dc = _DIRS[direction]
                nxt = (row + dr, col + dc)
                if nxt not in parent:
                    parent[nxt] = cell
                    stack.append(nxt)

        raise RuntimeError(\"No path found between start and end.\")
